Use ASP.NET Core's `WebApplicationFactory<T>` to host your server in-memory and send MCP requests via its `HttpClient`:

```csharp
// MyMcpServerTests.cs
using Microsoft.AspNetCore.Mvc.Testing;
using System.Net.Http.Json;
using System.Text.Json;

public class McpIntegrationTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly HttpClient _client;

    public McpIntegrationTests(WebApplicationFactory<Program> factory)
    {
        _client = factory.CreateClient();
    }

    [Fact]
    public async Task Initialize_ReturnsCapabilities()
    {
        var request = new
        {
            jsonrpc = "2.0",
            id = 1,
            method = "initialize",
            @params = new
            {
                protocolVersion = "2025-03-26",
                capabilities = new { },
                clientInfo = new { name = "test-client", version = "1.0" }
            }
        };

        var response = await _client.PostAsJsonAsync("/mcp", request);

        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        Assert.Equal("2025-03-26",
            body.GetProperty("result").GetProperty("protocolVersion").GetString());
    }

    [Fact]
    public async Task ToolsCall_ExecutesTool()
    {
        // Initialize first (required by protocol)
        await InitializeSession();

        var request = new
        {
            jsonrpc = "2.0",
            id = 2,
            method = "tools/call",
            @params = new
            {
                name = "my-tool",
                arguments = new { input = "hello" }
            }
        };

        var response = await _client.PostAsJsonAsync("/mcp", request);

        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        var content = body.GetProperty("result").GetProperty("content");
        Assert.False(content.EnumerateArray().First()
            .GetProperty("text").GetString() == null);
    }

    private async Task InitializeSession() { /* send initialize + initialized */ }
}
```

**Key points:**

- **`WebApplicationFactory<Program>`** boots your full middleware pipeline in-process — no port, no network.
- Send JSON-RPC requests to whatever endpoint your MCP server listens on (e.g., `/mcp` or `/sse`).
- For **Streamable HTTP** (session-based), capture the `Mcp-Session-Id` header from the initialize response and attach it to subsequent requests.
- For **SSE transport**, use `HttpClient.GetStreamAsync` and parse the `text/event-stream` lines.
- Mock external dependencies by overriding services in the factory's `WithWebHostBuilder` if needed.
